import { createTheme } from '@mui/material';

export const theme = createTheme({
  palette: {
    primary: {
      main: '#2C3E50',
    },
    secondary: {
      main: '#E67E22',
    },
    background: {
      default: '#ECF0F1',
      paper: '#FFFFFF',
    }
  },
});
